/** By member name; a value this build does not know stays a number. */
template <class E>
cJSON *json_enum(E v)
{
    const char *name = to_name(v);
    return name != nullptr ? cJSON_CreateString(name) : json_number(std::to_underlying(v));
}

template <class A, class F>
cJSON *json_array(const A &items, F element)
{
    cJSON *arr = cJSON_CreateArray();
    if (arr == nullptr) {
        return nullptr;
    }
    for (const auto &e : items) {
        cJSON *item = element(e);
        if (item == nullptr || !cJSON_AddItemToArray(arr, item)) {
            cJSON_Delete(item);
            cJSON_Delete(arr);
            return nullptr;
        }
    }
    return arr;
}

/** Adds `item` (which may be nullptr after an allocation failure) under `key`; false on failure. */
[[maybe_unused]] bool add(cJSON *obj, const char *key, cJSON *item)
{
    if (item == nullptr) {
        return false;
    }
    if (!cJSON_AddItemToObject(obj, key, item)) {
        cJSON_Delete(item);
        return false;
    }
    return true;
}

[[maybe_unused]] cJSON *finish(cJSON *obj, bool ok)
{
    if (!ok) {
        cJSON_Delete(obj);
        return nullptr;
    }
    return obj;
}

/** A body without known fields as {}. */
[[maybe_unused]] cJSON *json_empty(std::span<const uint8_t> body)
{
    return fr::proto::decode_empty(body) ? cJSON_CreateObject() : nullptr;
}

/** A decoded body as JSON; a value the schema rejects (valid()) is refused, as the TS decodeJson does. */
template <class T>
cJSON *json_of(const std::expected<T, fr::wire::DecodeErr> &v)
{
    return v && valid(*v) ? to_json(*v) : nullptr;
}

