    case RadioTx::kId:
        return radio_tx_to_json(cls, member_id, body);
    case Camera::kId:
        return camera_to_json(cls, member_id, body);
    case Scale::kId:
        return scale_to_json(cls, member_id, body);
    case Battery::kId:
        return battery_to_json(cls, member_id, body);
    case Haptic::kId:
